#!/usr/bin/env python3
"""Record manufacturer pin evidence separately from not-yet-created EDA identities."""
import json,hashlib,re
from pathlib import Path
R=Path(__file__).resolve().parents[1]
rows={}
def add(key,mpn,maker,pins,sources,search,ratings,notes,status='DOCUMENT_PINS_REVIEWED_LIBRARY_NOT_CREATED'):
 rows[key]={'manufacturer':maker,'mpn':mpn,'lcsc':None,'library_uuid':None,'device_uuid':None,'symbol_uuid':None,'footprint_uuid':None,'physical_pin_functions':pins,'sources':sources,'absence_search':search,'ratings':ratings,'review_status':status,'notes':notes,'native_load_test':'NOT_PERFORMED'}
add('tube_6h30pi_eb','6H30Pi-EB','Electro-Harmonix',{'1':'second triode plate','2':'second triode grid','3':'second triode cathode','4':'heater','5':'heater','6':'first triode plate','7':'first triode grid','8':'first triode cathode','9':'internal screen'},['evidence/datasheets/6H30Pi-EB.pdf pp1-2'],['evidence/library/alternatives-confirmed.json'],{'heater_V_min':6,'heater_V_max':6.6,'heater_A_max':.9,'plate_V_max':250,'plate_W_per_triode_max':4,'cathode_A_avg_max':.1,'self_bias_grid_resistance_ohm_max':300000,'design_nominal_plate_W_max':3.2},'Manufacturer numbered leads checked visually. Keep triodes6/7/8 and1/2/3 plus heater4/5 and screen9 as one physical bottle. No unverified socket footprint is assigned. 6H30Pi and6H30Pi-EB limits must not be combined to loosen constraints.')
add('relay_hv','67-1-A-12/1','Pickering',{'1':'normally open contact end1','2':'coil terminal (positive in diode variant)','3':'coil terminal','4':'normally open contact end4'},['evidence/datasheets/pickering-67-2020.pdf p2','https://www.pickeringrelay.com/product/67-1-a-12-1/'],['evidence/library/final-exception-review.json'],{'coil_V':12,'coil_ohm':150,'contact_power_W_max':50,'switch_A_max':3,'switch_DC_V_max':3500,'release_s_max':.002,'operate_s_max_including_bounce':.003,'contact_initial_ohm_max':.12},'No D suffix: no internal flyback diode. Voltage,current,power limits apply simultaneously; capacitive load and fault interruption are not qualified by resistive switch voltage. Use conservative2020carry current3A, not newer3.5A to relax review.')
add('mains_inlet','6100.3100','Schurter',{'L':'line terminal markedL','N':'neutral terminal markedN','PE':'protective-earth terminal markedearth'},['evidence/datasheets/schurter-6100.pdf'],['evidence/library/exception-search.json'],{'rated_AC_V':250,'rated_A':10},'Use actual terminal markings, not fictional numeric pins. C14 ClassI solder-terminal option. Do not infer L/N positions from front vs rear view; final harness drawing must repeat manufacturer view.')
add('mains_switch','R5ABLKBLKFF0','E-Switch',{'1':'poleA end1','1a':'poleA end2','2':'poleB end1','2a':'poleB end2'},['evidence/datasheets/R5ABLKBLKFF0.pdf'],['evidence/library/alternatives-confirmed.json'],{'rated_AC_V':250,'rated_A_at250VAC':16,'poles':2},'Non-illuminated DPST. Exact manufacturer drawing contact pairs1-1a and2-2a; numbers defined by manufacturer drawing, not a claim of moulded terminal labels.')
add('tube_socket','VT9-ST-C','Belton',{str(i):'mating tube lead'+str(i) for i in range(1,10)},['evidence/datasheets/belton-9pin.pdf p52'],['evidence/library/exact-film-socket.json'],{},'Manufacturer9-pin socket drawing has numbered contacts and dimensions. Catalogue does not establish current/voltage/temperature rating. Tube heater requires up to0.9A per contact; obtain rated socket data before approving assembly.','PIN_DRAWING_REVIEWED_RATINGS_MISSING')
add('transformer','QPCB-TX-6H30-100VA-DRAFT','Custom procurement specification',{},[],[],{'primary_Vrms':220,'primary_Hz':50,'provisional_HV_Vrms':150,'provisional_HV_A':.25,'provisional_heater_Vrms':9.5,'provisional_heater_A':5,'provisional_aux_Vrms':12,'provisional_aux_A':.3},'Winding values are requirements for a new supplier design, not verified hardware. No physical pin numbers assigned. Winding resistance, regulation, insulation, temperature rise, inrush and supplier terminal drawing are still required. This record cannot enter an approved physical topology.','SUPPLIER_TERMINALS_UNCONFIRMED')
for row in rows.values():
 row['local_source_sha256']={re.split(r' pp?\d',s)[0]:hashlib.sha256((R/re.split(r' pp?\d',s)[0]).read_bytes()).hexdigest() for s in row['sources'] if not s.startswith('http') and (R/re.split(r' pp?\d',s)[0]).is_file()}
state=R/'evidence/eda/fixture-reopened-state.json'
if state.exists():
 s=json.loads(state.read_text());v=[c for c in s['components'] if c['designator']=='V1'];assert len(v)==3
 assert sorted(p['number'] for c in v for p in c['pins'])==list('123456789')
 rows['tube_6h30pi_eb'].update(library_uuid=v[0]['component']['libraryUuid'],device_uuid=v[0]['component']['uuid'],symbol_uuid=v[0]['symbol']['uuid'],native_load_test='DISPLAY_AND_REOPEN_CHECKED; NATIVE_NETLIST_AND_DRC_FAILED',native_binding_scope={'project_uuid':s['source']['project_uuid'],'evidence':str(state.relative_to(R))})
(R/'parts.exceptions.json').write_text(json.dumps({'format':'quickpcb-parts-exceptions/v1','status':'NOT_ALL_APPROVED','parts':rows},ensure_ascii=False,indent=2)+'\n')
print('Recorded',len(rows),'exceptions; native tube display/reopen evidence included if available. No full load-gate pass is claimed.')
